using System;using System.Collections.Generic;using System.Data;using System.Globalization;using System.Web.Services;using System.Web.UI;using WebPortal.App_Code.BLL;
namespace WebPortal.Admin{public partial class RecruitmentReport:Page{protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static RecruitmentResult GetReport(string fromDate,string toDate,string reportType){DateTime f,t;if(!DateTime.TryParseExact(fromDate,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out f)||!DateTime.TryParseExact(toDate,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out t)||f>t)throw new ArgumentException("Invalid date range.");string from=f.ToString("dd-MMM-yyyy"),to=t.ToString("dd-MMM-yyyy");bllMaster b=new bllMaster();DataTable summary=reportType=="Location wise"?b.GetRecruitementReport_FinalSummary_LocationWise(from,to):reportType=="Position wise"?b.GetRecruitementReport_FinalSummary_LocationWithPosition(from,to):b.GetRecruitementReport_FinalSummary(from,to);return new RecruitmentResult{Summary=Pack(summary),Details=Pack(b.GetViewRecruitmentReport(from,to)),CandidateSummary=Pack(b.BindgrdCandidateSummary(from,to)),CandidateDetails=Pack(b.BindgrdCandidateDetails(from,to))};}static TableData Pack(DataTable t){TableData x=new TableData();if(t==null)return x;foreach(DataColumn c in t.Columns)x.Columns.Add(c.ColumnName);foreach(DataRow r in t.Rows){Dictionary<string,object>d=new Dictionary<string,object>();foreach(DataColumn c in t.Columns)d[c.ColumnName]=r[c]==DBNull.Value?"":r[c] is DateTime?((DateTime)r[c]).ToString("dd-MMM-yyyy"):r[c];x.Rows.Add(d);}return x;}}public class RecruitmentResult{public TableData Summary{get;set;}public TableData Details{get;set;}public TableData CandidateSummary{get;set;}public TableData CandidateDetails{get;set;}}public class TableData{public List<string> Columns{get;set;}=new List<string>();public List<Dictionary<string,object>> Rows{get;set;}=new List<Dictionary<string,object>>();}}
